'use client'

import type { ColumnDef } from '@tanstack/react-table'
import { Badge } from '#/components/ui/badge'
import { Checkbox } from '#/components/ui/checkbox'
import { cn } from '#/lib/utils.ts'
import type { Department, Employee, EmployeeStatus } from './data'

const statusClassName: Record<EmployeeStatus, string> = {
  Active:
    'bg-emerald-100 text-emerald-800 dark:bg-emerald-500/15 dark:text-emerald-300',
  Remote: 'bg-sky-100 text-sky-800 dark:bg-sky-500/15 dark:text-sky-300',
  'On leave':
    'bg-amber-100 text-amber-800 dark:bg-amber-500/15 dark:text-amber-300',
  Probation:
    'bg-violet-100 text-violet-800 dark:bg-violet-500/15 dark:text-violet-300',
}

const departmentDot: Record<Department, string> = {
  Engineering: 'bg-blue-500',
  Design: 'bg-pink-500',
  Sales: 'bg-emerald-500',
  Marketing: 'bg-orange-500',
  Finance: 'bg-teal-500',
  'People Ops': 'bg-violet-500',
  Support: 'bg-amber-500',
}

const currency = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
})

// Dates are stored as ISO strings; formatting in UTC keeps the server and the
// browser from disagreeing about which day it is.
const dateFormat = new Intl.DateTimeFormat('en-US', {
  year: 'numeric',
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
})

function initials(name: string) {
  return name
    .split(' ')
    .map((part) => part[0])
    .join('')
    .slice(0, 2)
}

// A fixed "today" keeps tenure stable across renders and between server and
// client; swap it for Date.now() in a real app.
const REFERENCE_DATE = Date.UTC(2025, 9, 1)

function tenure(hireDate: string) {
  const months = Math.max(
    0,
    Math.floor(
      (REFERENCE_DATE - new Date(`${hireDate}T00:00:00Z`).getTime()) /
        (1000 * 60 * 60 * 24 * 30.44),
    ),
  )
  const years = Math.floor(months / 12)
  return years > 0 ? `${years}y ${months % 12}m` : `${months}m`
}

export const columns: ColumnDef<Employee>[] = [
  {
    id: 'select',
    enableSorting: false,
    header: ({ table }) => (
      <Checkbox
        checked={
          table.getIsAllPageRowsSelected() ||
          (table.getIsSomePageRowsSelected() && 'indeterminate')
        }
        onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
        aria-label="Select all rows on this page"
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => row.toggleSelected(!!value)}
        aria-label={`Select ${row.original.name}`}
      />
    ),
  },
  {
    accessorKey: 'name',
    header: 'Employee',
    cell: ({ row }) => (
      <div className="flex items-center gap-3">
        <span
          aria-hidden
          className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-medium text-muted-foreground"
        >
          {initials(row.original.name)}
        </span>
        <div className="min-w-0">
          <p className="truncate font-medium">{row.original.name}</p>
          <p className="truncate text-xs text-muted-foreground">
            {row.original.email}
          </p>
        </div>
      </div>
    ),
  },
  {
    accessorKey: 'role',
    header: 'Role',
    cell: ({ row }) => (
      <div>
        <p>{row.original.role}</p>
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <span
            aria-hidden
            className={cn(
              'size-1.5 rounded-full',
              departmentDot[row.original.department],
            )}
          />
          {row.original.department}
        </p>
      </div>
    ),
  },
  {
    // Hidden in the table (shown under Role instead) but kept as a real column
    // so the toolbar can filter on it.
    accessorKey: 'department',
    header: 'Department',
    filterFn: 'equalsString',
  },
  {
    accessorKey: 'status',
    header: 'Status',
    filterFn: 'equalsString',
    cell: ({ row }) => (
      <Badge
        variant="outline"
        className={cn(
          'border-transparent',
          statusClassName[row.original.status],
        )}
      >
        {row.original.status}
      </Badge>
    ),
  },
  { accessorKey: 'location', header: 'Location' },
  { accessorKey: 'manager', header: 'Manager' },
  {
    accessorKey: 'hireDate',
    header: 'Hired',
    cell: ({ row }) => (
      <div className="tabular-nums">
        <p>
          {dateFormat.format(new Date(`${row.original.hireDate}T00:00:00Z`))}
        </p>
        <p className="text-xs text-muted-foreground">
          {tenure(row.original.hireDate)}
        </p>
      </div>
    ),
  },
  {
    accessorKey: 'performance',
    header: 'Performance',
    cell: ({ row }) => (
      <div
        role="img"
        aria-label={`${row.original.performance} out of 5`}
        className="flex gap-0.5"
      >
        {Array.from({ length: 5 }, (_, i) => (
          <span
            key={i}
            className={cn(
              'h-1.5 w-4 rounded-full',
              i < row.original.performance ? 'bg-primary' : 'bg-muted',
            )}
          />
        ))}
      </div>
    ),
  },
  {
    accessorKey: 'salary',
    header: () => <div className="text-right">Salary</div>,
    cell: ({ row }) => (
      <div className="text-right font-medium tabular-nums">
        {currency.format(row.original.salary)}
      </div>
    ),
  },
]

'use client'

import { useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type {
  Column,
  ColumnDef,
  FilterFn,
  SortingState,
} from '@tanstack/react-table'
import { ArrowDown, ArrowUp, ArrowUpDown } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { Input } from '#/components/ui/input'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import type { Employee } from './data'

type Density = 'compact' | 'comfortable' | 'spacious'

// Padding and type size live on the cells, so every column follows the toggle
// without its own cell renderer knowing about density.
const densityCell: Record<Density, string> = {
  compact: 'py-1 text-xs',
  comfortable: 'py-2 text-sm',
  spacious: 'py-4 text-base',
}

const densityHead: Record<Density, string> = {
  compact: 'h-8 text-xs',
  comfortable: 'h-10 text-sm',
  spacious: 'h-14 text-base',
}

// Searches the fields a person would actually type: name, email, role,
// department and location — not just the columns that happen to be strings.
const employeeSearch: FilterFn<Employee> = (row, _columnId, value) => {
  const query = String(value).trim().toLowerCase()
  if (!query) return true
  const { name, email, role, department, location } = row.original
  return [name, email, role, department, location].some((field) =>
    field.toLowerCase().includes(query),
  )
}

function ToolbarSelect<TData>({
  column,
  label,
  allLabel,
  options,
}: {
  column?: Column<TData, unknown>
  label: string
  allLabel: string
  options: string[]
}) {
  const value = (column?.getFilterValue() as string | undefined) ?? 'all'

  return (
    <Select
      value={value}
      onValueChange={(next) =>
        column?.setFilterValue(next === 'all' ? undefined : next)
      }
    >
      <SelectTrigger className="w-40" aria-label={`Filter by ${label}`}>
        <SelectValue placeholder={label} />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>
          <SelectItem value="all">{allLabel}</SelectItem>
          {options.map((option) => (
            <SelectItem key={option} value={option}>
              {option}
            </SelectItem>
          ))}
        </SelectGroup>
      </SelectContent>
    </Select>
  )
}

interface DataTableProps<TValue> {
  columns: ColumnDef<Employee, TValue>[]
  data: Employee[]
  departments: string[]
  statuses: string[]
}

export function DataTable<TValue>({
  columns,
  data,
  departments,
  statuses,
}: DataTableProps<TValue>) {
  const [sorting, setSorting] = useState<SortingState>([])
  const [globalFilter, setGlobalFilter] = useState('')
  const [density, setDensity] = useState<Density>('comfortable')

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    globalFilterFn: employeeSearch,
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getRowId: (row) => row.id,
    initialState: {
      pagination: { pageSize: 10 },
      // Department is rendered under Role, so its own column stays hidden
      // while still being filterable from the toolbar.
      columnVisibility: { department: false },
    },
    state: { sorting, globalFilter },
  })

  const { pageIndex, pageSize } = table.getState().pagination
  const filteredCount = table.getFilteredRowModel().rows.length
  const selectedCount = table.getFilteredSelectedRowModel().rows.length
  const from = filteredCount === 0 ? 0 : pageIndex * pageSize + 1
  const to = Math.min((pageIndex + 1) * pageSize, filteredCount)

  return (
    <div>
      <div className="mb-3 flex flex-wrap items-center gap-2">
        <Input
          type="search"
          placeholder="Search name, email, role, location..."
          aria-label="Search employees"
          value={globalFilter}
          onChange={(e) => table.setGlobalFilter(e.target.value)}
          className="w-full sm:w-72"
        />
        <ToolbarSelect
          column={table.getColumn('department')}
          label="Department"
          allLabel="All departments"
          options={departments}
        />
        <ToolbarSelect
          column={table.getColumn('status')}
          label="Status"
          allLabel="All statuses"
          options={statuses}
        />
        <Select
          value={density}
          onValueChange={(value) => setDensity(value as Density)}
        >
          <SelectTrigger className="w-40 sm:ml-auto" aria-label="Row density">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              <SelectItem value="compact">Compact</SelectItem>
              <SelectItem value="comfortable">Comfortable</SelectItem>
              <SelectItem value="spacious">Spacious</SelectItem>
            </SelectGroup>
          </SelectContent>
        </Select>
      </div>

      <div className="overflow-x-auto rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  const canSort = header.column.getCanSort()
                  const sorted = header.column.getIsSorted()
                  return (
                    <TableHead
                      key={header.id}
                      className={densityHead[density]}
                      aria-sort={
                        sorted === 'asc'
                          ? 'ascending'
                          : sorted === 'desc'
                            ? 'descending'
                            : undefined
                      }
                    >
                      {header.isPlaceholder ? null : canSort ? (
                        <button
                          type="button"
                          onClick={header.column.getToggleSortingHandler()}
                          className="flex w-full cursor-pointer items-center gap-2 whitespace-nowrap select-none"
                        >
                          {flexRender(
                            header.column.columnDef.header,
                            header.getContext(),
                          )}
                          {sorted === 'asc' ? (
                            <ArrowUp className="h-3 w-3 shrink-0" />
                          ) : sorted === 'desc' ? (
                            <ArrowDown className="h-3 w-3 shrink-0" />
                          ) : (
                            <ArrowUpDown className="h-3 w-3 shrink-0 opacity-50" />
                          )}
                        </button>
                      ) : (
                        flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )
                      )}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() ? 'selected' : undefined}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className={densityCell[density]}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={table.getVisibleLeafColumns().length}
                  className="h-24 text-center"
                >
                  No employees match your filters.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-2 py-3">
        <p className="text-sm text-muted-foreground" aria-live="polite">
          {selectedCount > 0 ? `${selectedCount} selected · ` : null}
          Showing {from}–{to} of {filteredCount} employees
        </p>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          <span className="text-sm tabular-nums text-muted-foreground">
            Page {pageIndex + 1} of {Math.max(table.getPageCount(), 1)}
          </span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  )
}

import { columns } from './columns'
import { DataTable } from './data-table'
import { departments, employees, statuses } from './data'

export function CrmEmployeesTableDemo() {
  return (
    <DataTable
      columns={columns}
      data={employees}
      departments={departments}
      statuses={statuses}
    />
  )
}
